using System.Text.RegularExpressions;
using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class CharacterizeCompositeResolverTemplateTests
{
    [Fact]
    public async Task EmitsResolverWithInstanceFormatterLookupAndRegisteredDependencies()
    {
        const string source = """
            using MessagePack;

            namespace Demo
            {
                [MessagePackObject]
                public class Sample
                {
                    [Key(0)]
                    public int Value { get; set; }
                }

                [GeneratedMessagePackResolver]
                public partial class TestResolver
                {
                }
            }
            """;

        string[] generatedSources = await RunGeneratorAsync(source);
        string resolverText = generatedSources.Single(text =>
            text.Contains("partial class TestResolver", StringComparison.Ordinal) &&
            text.Contains("MsgPack::IFormatterResolver", StringComparison.Ordinal));
        string sampleFormatterText = generatedSources.Single(text =>
            text.Contains("IMessagePackFormatter<global::Demo.Sample>", StringComparison.Ordinal));

        Match formatterDeclaration = Regex.Match(
            sampleFormatterText,
            @"class\s+(?<name>\w+)\s*:\s*MsgPack::Formatters\.IMessagePackFormatter<global::Demo\.Sample>");
        formatterDeclaration.Success.Should().BeTrue();

        resolverText.Should().Contain("partial class TestResolver");
        resolverText.Should().Contain("TestResolver Instance");
        resolverText.Should().Contain("GetFormatter<T>()");
        resolverText.Should().Contain("FormatterCache<T>");
        resolverText.Should().Contain("formatterList");
        resolverText.Should().Contain("resolverList");
        resolverText.Should().Contain(formatterDeclaration.Groups["name"].Value);
        resolverText.Should().Contain("GeneratedResolver.Instance");
    }

    private static async Task<string[]> RunGeneratorAsync(string source)
    {
        ImmutableArray<MetadataReference> references = (await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None))
            .AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "Receipts.CompositeResolver.Characterization",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.CSharp7_3)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(
            compilation,
            out Compilation outputCompilation,
            out ImmutableArray<Diagnostic> generatorDiagnostics);

        generatorDiagnostics.Should().BeEmpty();
        outputCompilation.GetDiagnostics().Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error).Should().BeEmpty();
        return driver.GetRunResult().Results
            .SelectMany(result => result.GeneratedSources)
            .Select(generatedSource => generatedSource.SourceText.ToString())
            .ToArray();
    }
}

