using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class CharacterizeTransformUtilitiesNestingTests
{
    [Fact]
    public async Task WrapsFormatterInNamespaceAndNestingClass()
    {
        const string source = """
            using MessagePack;

            namespace Demo
            {
                public partial class Outer
                {
                    [MessagePackObject]
                    public class Inner
                    {
                        [Key(0)]
                        public int Value { get; set; }
                    }
                }
            }
            """;

        string[] generatedSources = await RunGeneratorAsync(source);
        string formatterText = generatedSources.Single(text =>
            text.Contains("IMessagePackFormatter<global::Demo.Outer.Inner>", StringComparison.Ordinal));

        formatterText.Should().Contain("namespace Demo");
        formatterText.Should().Contain("public partial class Outer");
    }

    [Fact]
    public async Task WrapsFormatterInNestingRecord()
    {
        const string source = """
            using MessagePack;

            namespace DemoRecords
            {
                public partial record Outer
                {
                    [MessagePackObject]
                    public class Inner
                    {
                        [Key(0)]
                        public int Value { get; set; }
                    }
                }
            }
            """;

        string[] generatedSources = await RunGeneratorAsync(source, LanguageVersion.CSharp9);
        string formatterText = generatedSources.Single(text =>
            text.Contains("IMessagePackFormatter<global::DemoRecords.Outer.Inner>", StringComparison.Ordinal));

        formatterText.Should().Contain("namespace DemoRecords");
        formatterText.Should().Contain("public partial record Outer");
    }

    private static async Task<string[]> RunGeneratorAsync(string source, LanguageVersion languageVersion = LanguageVersion.CSharp7_3)
    {
        ImmutableArray<MetadataReference> references = (await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None))
            .AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "Receipts.TransformUtilities.Characterization",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(languageVersion)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(
            compilation,
            out Compilation outputCompilation,
            out ImmutableArray<Diagnostic> generatorDiagnostics);

        generatorDiagnostics.Should().BeEmpty();
        outputCompilation.GetDiagnostics().Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error).Should().BeEmpty();
        return driver.GetRunResult().Results
            .SelectMany(result => result.GeneratedSources)
            .Select(generatedSource => generatedSource.SourceText.ToString())
            .ToArray();
    }
}
